-- Generic append-only enforcement for immutable evidence rows.
CREATE FUNCTION public.kora_reject_row_mutation()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $$
BEGIN
  RAISE EXCEPTION USING
    ERRCODE = '23514',
    MESSAGE = format('%I is append-only; %s is forbidden', TG_TABLE_NAME, TG_OP);
END;
$$;

CREATE TRIGGER "Order_immutable"
  BEFORE UPDATE OR DELETE ON "Order"
  FOR EACH ROW EXECUTE FUNCTION public.kora_reject_row_mutation();
