-- Recovery-code identity and hash never change. Consumption is a one-way
-- marker; set rotation/deletion remains a future authenticated transaction.
CREATE FUNCTION public.kora_guard_admin_recovery_code()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW."usedAt" IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'AdminRecoveryCode must be inserted unused';
    END IF;
    RETURN NEW;
  END IF;

  IF ROW(NEW."id", NEW."adminUserId", NEW."codeHash", NEW."createdAt")
     IS DISTINCT FROM
     ROW(OLD."id", OLD."adminUserId", OLD."codeHash", OLD."createdAt")
     OR (OLD."usedAt" IS NOT NULL AND NEW."usedAt" IS DISTINCT FROM OLD."usedAt") THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'AdminRecoveryCode hash and consumption proof are immutable';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "AdminRecoveryCode_durable_consumption"
  BEFORE INSERT OR UPDATE ON "AdminRecoveryCode"
  FOR EACH ROW EXECUTE FUNCTION public.kora_guard_admin_recovery_code();

-- Immutable server-assigned admin provenance.
CREATE FUNCTION public.kora_guard_catalog_provenance()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $$
BEGIN
  IF NEW."createdByAdminId" IS DISTINCT FROM OLD."createdByAdminId" THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = format('%I.createdByAdminId is immutable', TG_TABLE_NAME);
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "Artist_admin_provenance_immutable"
  BEFORE UPDATE OF "createdByAdminId" ON "Artist"
  FOR EACH ROW EXECUTE FUNCTION public.kora_guard_catalog_provenance();
CREATE TRIGGER "AudioContent_admin_provenance_immutable"
  BEFORE UPDATE OF "createdByAdminId" ON "AudioContent"
  FOR EACH ROW EXECUTE FUNCTION public.kora_guard_catalog_provenance();

-- Publication rows preserve their creator and proof. Only one monotonic
-- archival timestamp may be assigned; deletion and all other rewrites fail.
CREATE FUNCTION public.kora_guard_content_publication()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'ContentPublication is append-only; DELETE is forbidden';
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW."archivedAt" IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'ContentPublication must be inserted active';
    END IF;
    RETURN NEW;
  END IF;

  IF ROW(NEW."id", NEW."audioContentId", NEW."publishedByAdminId", NEW."publishedAt")
     IS DISTINCT FROM
     ROW(OLD."id", OLD."audioContentId", OLD."publishedByAdminId", OLD."publishedAt") THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'ContentPublication proof and admin provenance are immutable';
  END IF;

  IF NEW."archivedAt" IS DISTINCT FROM OLD."archivedAt"
     AND NOT (OLD."archivedAt" IS NULL AND NEW."archivedAt" IS NOT NULL) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'ContentPublication.archivedAt may only be assigned once';
  END IF;

  RETURN NEW;
END;
$$;

CREATE TRIGGER "ContentPublication_append_only"
  BEFORE INSERT OR UPDATE OR DELETE ON "ContentPublication"
  FOR EACH ROW EXECUTE FUNCTION public.kora_guard_content_publication();

-- Payment attempts are immutable except for the one-time provider reference.
CREATE FUNCTION public.kora_guard_payment_attempt()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'PaymentAttempt is immutable; DELETE is forbidden';
  END IF;

  IF ROW(NEW."id", NEW."orderId", NEW."provider", NEW."amountCfa", NEW."currency", NEW."idempotencyKey", NEW."createdAt")
     IS DISTINCT FROM
     ROW(OLD."id", OLD."orderId", OLD."provider", OLD."amountCfa", OLD."currency", OLD."idempotencyKey", OLD."createdAt") THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'PaymentAttempt immutable fields cannot be rewritten';
  END IF;

  IF OLD."providerReference" IS NOT NULL
     AND NEW."providerReference" IS DISTINCT FROM OLD."providerReference" THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'PaymentAttempt.providerReference may only be assigned once';
  END IF;

  RETURN NEW;
END;
$$;

CREATE TRIGGER "PaymentAttempt_immutable"
  BEFORE UPDATE OR DELETE ON "PaymentAttempt"
  FOR EACH ROW EXECUTE FUNCTION public.kora_guard_payment_attempt();

-- Media lifecycle and provider identifiers are server-controlled. Provider
-- identifiers and the provider itself cannot be reassigned after attribution.
CREATE FUNCTION public.kora_guard_media_asset()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'MediaAsset evidence cannot be deleted';
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW."processingStatus" <> 'PREPARING' THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'MediaAsset must start in PREPARING';
    END IF;
    RETURN NEW;
  END IF;

  IF ROW(NEW."id", NEW."audioContentId", NEW."kind", NEW."version", NEW."createdAt")
     IS DISTINCT FROM ROW(OLD."id", OLD."audioContentId", OLD."kind", OLD."version", OLD."createdAt") THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'MediaAsset identity and version are immutable';
  END IF;

  IF OLD."privateProviderUploadRef" IS NOT NULL
     AND NEW."privateProviderUploadRef" IS DISTINCT FROM OLD."privateProviderUploadRef" THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'MediaAsset.privateProviderUploadRef may only be assigned once';
  END IF;
  IF OLD."privateProviderAssetRef" IS NOT NULL
     AND NEW."privateProviderAssetRef" IS DISTINCT FROM OLD."privateProviderAssetRef" THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'MediaAsset.privateProviderAssetRef may only be assigned once';
  END IF;
  IF OLD."provider" IS NOT NULL
     AND NEW."provider" IS DISTINCT FROM OLD."provider" THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'MediaAsset.provider is immutable after attribution';
  END IF;

  IF NEW."processingStatus" IS DISTINCT FROM OLD."processingStatus"
     AND NOT (CASE OLD."processingStatus"
       WHEN 'PREPARING' THEN NEW."processingStatus" IN ('UPLOAD_PENDING', 'FAILED')
       WHEN 'UPLOAD_PENDING' THEN NEW."processingStatus" IN ('PROCESSING', 'FAILED')
       WHEN 'PROCESSING' THEN NEW."processingStatus" IN ('READY', 'FAILED')
       ELSE FALSE
     END) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'invalid MediaAsset processing-state transition';
  END IF;

  RETURN NEW;
END;
$$;

CREATE TRIGGER "MediaAsset_lifecycle_and_references"
  BEFORE INSERT OR UPDATE OR DELETE ON "MediaAsset"
  FOR EACH ROW EXECUTE FUNCTION public.kora_guard_media_asset();

-- Inbox rows are durable. Only their processing status and completion marker
-- can advance along the contracted state machine.
CREATE FUNCTION public.kora_guard_payment_inbox()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'PaymentWebhookInbox is durable; DELETE is forbidden';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW."processingStatus" <> 'RECEIVED' OR NEW."processedAt" IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'PaymentWebhookInbox must start in RECEIVED';
    END IF;
  ELSE
    IF ROW(NEW."id", NEW."provider", NEW."providerEventKey", NEW."paymentAttemptId", NEW."payloadHash", NEW."encryptedPayload", NEW."signatureVerifiedAt", NEW."receivedAt")
       IS DISTINCT FROM
       ROW(OLD."id", OLD."provider", OLD."providerEventKey", OLD."paymentAttemptId", OLD."payloadHash", OLD."encryptedPayload", OLD."signatureVerifiedAt", OLD."receivedAt") THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'PaymentWebhookInbox evidence is immutable';
    END IF;
    IF OLD."processedAt" IS NOT NULL
       AND NEW."processedAt" IS DISTINCT FROM OLD."processedAt" THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'PaymentWebhookInbox.processedAt may only be assigned once';
    END IF;
    IF NEW."processingStatus" IS DISTINCT FROM OLD."processingStatus"
       AND NOT (CASE OLD."processingStatus"
         WHEN 'RECEIVED' THEN NEW."processingStatus" IN ('PROCESSING', 'REJECTED')
         WHEN 'PROCESSING' THEN NEW."processingStatus" IN ('PROCESSED', 'REJECTED')
         ELSE FALSE
       END) THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'invalid PaymentWebhookInbox state transition';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "PaymentWebhookInbox_durable_state"
  BEFORE INSERT OR UPDATE OR DELETE ON "PaymentWebhookInbox"
  FOR EACH ROW EXECUTE FUNCTION public.kora_guard_payment_inbox();

